with with_windows as (select *, row_number() over (partition by page order by duration_sec desc, id asc) row_seq, max(duration_sec) over (order by cast(event_time as bigint) asc range between 7776000 preceding and current row) duration_sec_max_90d, sum(duration_sec) over (partition by session_id order by cast(event_time as bigint) asc range between 2592000 preceding and current row) duration_sec_sum_30d from web_events where to_date(event_time) < '2023-05-13') select date_trunc('month', event_time) as activity_month, percentile_approx(duration_sec_max_90d, 0.95) as duration_sec_max_90d_p95, count(distinct session_id) as distinct_session_ids, count(distinct page) as distinct_pages, count(distinct id) as distinct_ids, round(avg(duration_sec_max_90d), 2) as avg_duration_sec_max_90d from with_windows group by 1 order by duration_sec_max_90d_p95 desc
